  1→const express = require('express');
  2→const cors = require('cors');
  3→const http = require('http');
  4→const rateLimit = require('express-rate-limit');
  5→const { createDb } = require('./db');
  6→const { authMiddleware } = require('./middleware/auth');
  7→const { createAuthRouter } = require('./routes/auth');
  8→const { createRoomsRouter } = require('./routes/rooms');
  9→const { setupWebSocket } = require('./ws');
 10→const { createStockfishPlayer } = require('./chess/stockfishPlayer');
 11→
 12→const PORT = process.env.PORT || 3001;
 13→
 14→async function main() {
 15→  // Initialize database
 16→  const db = createDb();
 17→
 18→  // Initialize Stockfish (non-blocking, AvE disabled if unavailable)
 19→  let stockfishPlayer = null;
 20→  createStockfishPlayer().then(player => {
 21→    stockfishPlayer = player;
 22→  }).catch(() => {
 23→    // Already logged in createStockfishPlayer
 24→  });
 25→
 26→  // Create Express app
 27→  const app = express();
 28→
 29→  // Middleware
 30→  app.use(express.json());
 31→  app.use(cors({
 32→    origin: ['http://localhost:5173', 'http://127.0.0.1:5173'],
 33→    credentials: true
 34→  }));
 35→
 36→  // Request logging
 37→  app.use((req, res, next) => {
 38→    const start = Date.now();
 39→    res.on('finish', () => {
 40→      const duration = Date.now() - start;
 41→      console.log(`${req.method} ${req.originalUrl} ${res.statusCode} ${duration}ms`);
 42→    });
 43→    next();
 44→  });
 45→
 46→  // Rate limiters
 47→  const signupLimiter = rateLimit({
 48→    windowMs: 60 * 1000, // 1 minute
 49→    max: 5,
 50→    standardHeaders: true,
 51→    legacyHeaders: false,
 52→    message: { error: 'Too many signup attempts. Try again in a minute.' }
 53→  });
 54→
 55→  const moveLimiter = rateLimit({
 56→    windowMs: 60 * 1000, // 1 minute
 57→    max: 60,
 58→    keyGenerator: (req) => req.user ? `user:${req.user.id}` : req.ip,
 59→    standardHeaders: true,
 60→    legacyHeaders: false,
 61→    message: { error: 'Too many moves. Slow down.' }
 62→  });
 63→
 64→  // Create HTTP server
 65→  const server = http.createServer(app);
 66→
 67→  // Setup WebSocket
 68→  const { broadcast } = setupWebSocket(server, db);
 69→
 70→  // Auth middleware instance
 71→  const auth = authMiddleware(db);
 72→
 73→  // Mount routes
 74→  app.use('/api/auth', signupLimiter, createAuthRouter(db));
 75→
 76→  const roomsRouter = createRoomsRouter(db, {
 77→    broadcast,
 78→    getStockfishPlayer: () => stockfishPlayer
 79→  });
 80→  app.use('/api/rooms', auth, roomsRouter);
 81→
 82→  // Apply move-specific rate limiter to move endpoint
 83→  app.use('/api/rooms/:id/move', moveLimiter);
 84→
 85→  // Health check
 86→  app.get('/api/health', (req, res) => {
 87→    res.json({
 88→      status: 'ok',
 89→      stockfish: !!stockfishPlayer
 90→    });
 91→  });
 92→
 93→  // Room expiry: every 5 minutes, delete stale waiting rooms
 94→  const expireStaleRooms = db.prepare(`
 95→    DELETE FROM rooms
 96→    WHERE status = 'waiting'
 97→    AND created_at < datetime('now', '-15 minutes')
 98→  `);
 99→  const expireStaleGameStates = db.prepare(`
100→    DELETE FROM game_states
101→    WHERE room_id NOT IN (SELECT id FROM rooms)
102→  `);
103→
104→  setInterval(() => {
105→    const result = expireStaleRooms.run();
106→    if (result.changes > 0) {
107→      expireStaleGameStates.run();
108→      console.log(`Expired ${result.changes} stale waiting room(s)`);
109→    }
110→  }, 5 * 60 * 1000);
111→
112→  // Start server
113→  server.listen(PORT, () => {
114→    console.log(`Chess server listening on http://localhost:${PORT}`);
115→    console.log(`WebSocket available at ws://localhost:${PORT}/api/rooms/:id/ws?token=xxx`);
116→  });
117→
118→  // Graceful shutdown
119→  process.on('SIGINT', () => {
120→    console.log('\nShutting down...');
121→    if (stockfishPlayer) stockfishPlayer.terminate();
122→    db.close();
123→    server.close();
124→    process.exit(0);
125→  });
126→}
127→
128→main().catch(err => {
129→  console.error('Failed to start server:', err);
130→  process.exit(1);
131→});
