 1→function authMiddleware(db) {
 2→  const findUser = db.prepare('SELECT id, username, passkey_address FROM users WHERE token = ?');
 3→
 4→  return (req, res, next) => {
 5→    const authHeader = req.headers.authorization;
 6→    if (!authHeader || !authHeader.startsWith('Bearer ')) {
 7→      return res.status(401).json({ error: 'Missing or invalid Authorization header' });
 8→    }
 9→
10→    const token = authHeader.slice(7);
11→    const user = findUser.get(token);
12→
13→    if (!user) {
14→      return res.status(401).json({ error: 'Invalid token' });
15→    }
16→
17→    req.user = user;
18→    next();
19→  };
20→}
21→
22→module.exports = { authMiddleware };
