 1→const express = require('express');
 2→const { v4: uuidv4 } = require('uuid');
 3→
 4→function createAuthRouter(db) {
 5→  const router = express.Router();
 6→
 7→  const insertUser = db.prepare('INSERT INTO users (username, token) VALUES (?, ?)');
 8→  const findByUsername = db.prepare('SELECT id, username, token FROM users WHERE username = ?');
 9→  const findByPasskey = db.prepare('SELECT id, username, token, passkey_address FROM users WHERE passkey_address = ?');
10→  const insertPasskeyUser = db.prepare('INSERT INTO users (username, token, passkey_address) VALUES (?, ?, ?)');
11→
12→  // POST /api/auth/signup
13→  router.post('/signup', (req, res) => {
14→    const { username } = req.body;
15→
16→    if (!username || typeof username !== 'string') {
17→      return res.status(400).json({ error: 'Username is required' });
18→    }
19→
20→    const trimmed = username.trim();
21→
22→    // Validate: 3-32 chars, alphanumeric + hyphens
23→    if (trimmed.length < 3 || trimmed.length > 32) {
24→      return res.status(400).json({ error: 'Username must be 3-32 characters' });
25→    }
26→
27→    if (!/^[a-zA-Z0-9-]+$/.test(trimmed)) {
28→      return res.status(400).json({ error: 'Username may only contain letters, numbers, and hyphens' });
29→    }
30→
31→    // Check uniqueness
32→    const existing = findByUsername.get(trimmed);
33→    if (existing) {
34→      return res.status(409).json({ error: 'Username already taken' });
35→    }
36→
37→    const token = uuidv4();
38→
39→    try {
40→      insertUser.run(trimmed, token);
41→      res.status(201).json({ token, username: trimmed });
42→    } catch (err) {
43→      // Handle race condition on unique constraint
44→      if (err.code === 'SQLITE_CONSTRAINT_UNIQUE') {
45→        return res.status(409).json({ error: 'Username already taken' });
46→      }
47→      throw err;
48→    }
49→  });
50→
51→  // POST /api/auth/token — bridge for passkey users
52→  router.post('/token', (req, res) => {
53→    const { passkeyAddress, username } = req.body;
54→
55→    if (!passkeyAddress || typeof passkeyAddress !== 'string') {
56→      return res.status(400).json({ error: 'passkeyAddress is required' });
57→    }
58→
59→    if (!username || typeof username !== 'string') {
60→      return res.status(400).json({ error: 'username is required' });
61→    }
62→
63→    const trimmedUsername = username.trim();
64→    if (trimmedUsername.length < 3 || trimmedUsername.length > 32) {
65→      return res.status(400).json({ error: 'Username must be 3-32 characters' });
66→    }
67→
68→    // Find existing user by passkey address
69→    const existing = findByPasskey.get(passkeyAddress);
70→    if (existing) {
71→      return res.json({ token: existing.token, username: existing.username });
72→    }
73→
74→    // Create new user with passkey address
75→    const token = uuidv4();
76→
77→    try {
78→      insertPasskeyUser.run(trimmedUsername, token, passkeyAddress);
79→      res.status(201).json({ token, username: trimmedUsername });
80→    } catch (err) {
81→      if (err.code === 'SQLITE_CONSTRAINT_UNIQUE') {
82→        return res.status(409).json({ error: 'Username already taken' });
83→      }
84→      throw err;
85→    }
86→  });
87→
88→  return router;
89→}
90→
91→module.exports = { createAuthRouter };
