  1→const express = require('express');
  2→const { v4: uuidv4 } = require('uuid');
  3→const {
  4→  createInitialGameState, serializeGameState, deserializeGameState,
  5→  parseMove, isMoveLegal, getLegalMoves, applyMove, getGameResult,
  6→  boardToFEN, indexToAlgebraic
  7→} = require('../chess/gameLogic');
  8→
  9→const CHESS_WORDS = ['ROOK', 'KING', 'PAWN', 'MATE', 'MOVE', 'PLAY', 'GAME', 'DRAW'];
 10→
 11→function generateInviteCode(db) {
 12→  const checkCode = db.prepare('SELECT id FROM rooms WHERE invite_code = ?');
 13→  for (let attempt = 0; attempt < 20; attempt++) {
 14→    const word = CHESS_WORDS[Math.floor(Math.random() * CHESS_WORDS.length)];
 15→    const num = String(Math.floor(Math.random() * 100)).padStart(2, '0');
 16→    const code = word + num;
 17→    if (!checkCode.get(code)) {
 18→      return code;
 19→    }
 20→  }
 21→  // Fallback to UUID prefix if all collide (extremely unlikely)
 22→  return uuidv4().slice(0, 8).toUpperCase();
 23→}
 24→
 25→function createRoomsRouter(db, { broadcast, getStockfishPlayer }) {
 26→  const router = express.Router();
 27→
 28→  // Prepared statements
 29→  const insertRoom = db.prepare(`
 30→    INSERT INTO rooms (invite_code, white_user_id, black_user_id, status, is_stockfish, stockfish_level)
 31→    VALUES (?, ?, ?, ?, ?, ?)
 32→  `);
 33→  const insertGameState = db.prepare(`
 34→    INSERT INTO game_states (room_id, board, current_turn, move_history, en_passant_target, moved_pieces, half_move_clock, position_history)
 35→    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
 36→  `);
 37→  const findRoomByCode = db.prepare('SELECT * FROM rooms WHERE invite_code = ?');
 38→  const findRoomById = db.prepare('SELECT * FROM rooms WHERE id = ?');
 39→  const findGameState = db.prepare('SELECT * FROM game_states WHERE room_id = ?');
 40→  const updateRoomJoin = db.prepare(`
 41→    UPDATE rooms SET white_user_id = ?, black_user_id = ?, status = 'playing', updated_at = datetime('now')
 42→    WHERE id = ?
 43→  `);
 44→  const updateGameState = db.prepare(`
 45→    UPDATE game_states
 46→    SET board = ?, current_turn = ?, move_history = ?, en_passant_target = ?,
 47→        moved_pieces = ?, half_move_clock = ?, position_history = ?, updated_at = datetime('now')
 48→    WHERE room_id = ?
 49→  `);
 50→  const updateRoomResult = db.prepare(`
 51→    UPDATE rooms SET status = 'finished', result = ?, updated_at = datetime('now') WHERE id = ?
 52→  `);
 53→  const findUserById = db.prepare('SELECT id, username FROM users WHERE id = ?');
 54→
 55→  // Stockfish system user
 56→  const findStockfishUser = db.prepare("SELECT id FROM users WHERE username = '__stockfish__'");
 57→  const insertStockfishUser = db.prepare("INSERT OR IGNORE INTO users (username, token) VALUES ('__stockfish__', '__stockfish_token__')");
 58→
 59→  function getOrCreateStockfishUser() {
 60→    let user = findStockfishUser.get();
 61→    if (!user) {
 62→      insertStockfishUser.run();
 63→      user = findStockfishUser.get();
 64→    }
 65→    return user.id;
 66→  }
 67→
 68→  // Track consecutive illegal moves per room per user
 69→  const illegalMoveCounters = new Map(); // `${roomId}:${userId}` -> count
 70→
 71→  function getIllegalKey(roomId, userId) {
 72→    return `${roomId}:${userId}`;
 73→  }
 74→
 75→  // POST /api/rooms — create a new room
 76→  router.post('/', (req, res) => {
 77→    const { color, opponent, stockfishLevel } = req.body;
 78→    const userId = req.user.id;
 79→
 80→    // Determine player's color
 81→    let chosenColor = color;
 82→    if (!chosenColor || chosenColor === 'random') {
 83→      chosenColor = Math.random() < 0.5 ? 'white' : 'black';
 84→    }
 85→    if (chosenColor !== 'white' && chosenColor !== 'black') {
 86→      return res.status(400).json({ error: 'color must be "white", "black", or "random"' });
 87→    }
 88→
 89→    const inviteCode = generateInviteCode(db);
 90→    const isStockfish = opponent === 'stockfish' ? 1 : 0;
 91→    const sfLevel = isStockfish ? (stockfishLevel || 10) : null;
 92→
 93→    // Check Stockfish availability
 94→    if (isStockfish) {
 95→      const sfPlayer = getStockfishPlayer();
 96→      if (!sfPlayer) {
 97→        return res.status(503).json({ error: 'Stockfish engine is not available on this server' });
 98→      }
 99→    }
100→
101→    let whiteUserId = chosenColor === 'white' ? userId : null;
102→    let blackUserId = chosenColor === 'black' ? userId : null;
103→    let status = 'waiting';
104→
105→    // If Stockfish opponent, fill the other seat immediately
106→    if (isStockfish) {
107→      const sfUserId = getOrCreateStockfishUser();
108→      if (chosenColor === 'white') {
109→        blackUserId = sfUserId;
110→      } else {
111→        whiteUserId = sfUserId;
112→      }
113→      status = 'playing';
114→    }
115→
116→    const createRoom = db.transaction(() => {
117→      const result = insertRoom.run(inviteCode, whiteUserId, blackUserId, status, isStockfish, sfLevel);
118→      const roomId = result.lastInsertRowid;
119→
120→      // Initialize game state
121→      const gs = createInitialGameState();
122→      const s = serializeGameState(gs);
123→      insertGameState.run(roomId, s.board, s.current_turn, s.move_history, s.en_passant_target, s.moved_pieces, s.half_move_clock, s.position_history);
124→
125→      return roomId;
126→    });
127→
128→    const roomId = createRoom();
129→
130→    // If Stockfish plays first (player chose black), trigger Stockfish move
131→    if (isStockfish && chosenColor === 'black') {
132→      triggerStockfishMove(roomId);
133→    }
134→
135→    res.status(201).json({
136→      roomId: Number(roomId),
137→      inviteCode,
138→      color: chosenColor
139→    });
140→  });
141→
142→  // POST /api/rooms/join — join a room by invite code
143→  router.post('/join', (req, res) => {
144→    const { inviteCode } = req.body;
145→    const userId = req.user.id;
146→
147→    if (!inviteCode || typeof inviteCode !== 'string') {
148→      return res.status(400).json({ error: 'inviteCode is required' });
149→    }
150→
151→    const room = findRoomByCode.get(inviteCode.toUpperCase());
152→    if (!room) {
153→      return res.status(404).json({ error: 'Room not found' });
154→    }
155→
156→    if (room.status !== 'waiting') {
157→      return res.status(400).json({ error: 'Room is no longer accepting players' });
158→    }
159→
160→    // Don't let the creator join their own room
161→    if (room.white_user_id === userId || room.black_user_id === userId) {
162→      return res.status(400).json({ error: 'You are already in this room' });
163→    }
164→
165→    // Assign joiner to empty seat
166→    let whiteUserId = room.white_user_id;
167→    let blackUserId = room.black_user_id;
168→    let myColor;
169→
170→    if (!whiteUserId) {
171→      whiteUserId = userId;
172→      myColor = 'white';
173→    } else {
174→      blackUserId = userId;
175→      myColor = 'black';
176→    }
177→
178→    updateRoomJoin.run(whiteUserId, blackUserId, room.id);
179→
180→    // Broadcast join event
181→    broadcast(room.id, 'join', {
182→      userId,
183→      username: req.user.username,
184→      color: myColor
185→    });
186→
187→    res.json({
188→      roomId: room.id,
189→      color: myColor
190→    });
191→  });
192→
193→  // GET /api/rooms/:id — get room and game state
194→  router.get('/:id', (req, res) => {
195→    const roomId = parseInt(req.params.id);
196→    if (isNaN(roomId)) {
197→      return res.status(400).json({ error: 'Invalid room ID' });
198→    }
199→
200→    const room = findRoomById.get(roomId);
201→    if (!room) {
202→      return res.status(404).json({ error: 'Room not found' });
203→    }
204→
205→    const gsRow = findGameState.get(roomId);
206→    if (!gsRow) {
207→      return res.status(404).json({ error: 'Game state not found' });
208→    }
209→
210→    const gameState = deserializeGameState(gsRow);
211→    const fen = boardToFEN(gameState);
212→    const legalMoves = room.status === 'playing' ? getLegalMoves(gameState) : [];
213→
214→    // Determine caller's color
215→    let myColor = null;
216→    if (req.user.id === room.white_user_id) myColor = 'white';
217→    else if (req.user.id === room.black_user_id) myColor = 'black';
218→
219→    // Get player names
220→    const whiteUser = room.white_user_id ? findUserById.get(room.white_user_id) : null;
221→    const blackUser = room.black_user_id ? findUserById.get(room.black_user_id) : null;
222→
223→    res.json({
224→      roomId: room.id,
225→      inviteCode: room.invite_code,
226→      status: room.status,
227→      isStockfish: !!room.is_stockfish,
228→      stockfishLevel: room.stockfish_level,
229→      result: room.result,
230→      white: whiteUser ? whiteUser.username : null,
231→      black: blackUser ? blackUser.username : null,
232→      myColor,
233→      fen,
234→      currentTurn: gameState.currentTurn,
235→      moveHistory: gameState.moveHistory,
236→      legalMoves,
237→      board: gameState.board
238→    });
239→  });
240→
241→  // POST /api/rooms/:id/move — submit a move
242→  router.post('/:id/move', (req, res) => {
243→    const roomId = parseInt(req.params.id);
244→    if (isNaN(roomId)) {
245→      return res.status(400).json({ error: 'Invalid room ID' });
246→    }
247→
248→    const { move } = req.body;
249→    if (!move || typeof move !== 'string') {
250→      return res.status(400).json({ error: 'move is required (UCI format, e.g. "e2e4")' });
251→    }
252→
253→    const parsed = parseMove(move);
254→    if (!parsed) {
255→      return res.status(400).json({ error: 'Invalid move format. Use UCI notation (e.g. "e2e4", "e7e8q")' });
256→    }
257→
258→    // Use a transaction to prevent race conditions
259→    const submitMove = db.transaction(() => {
260→      const room = findRoomById.get(roomId);
261→      if (!room) {
262→        return { status: 404, body: { error: 'Room not found' } };
263→      }
264→
265→      if (room.status !== 'playing') {
266→        return { status: 400, body: { error: 'Game is not in progress' } };
267→      }
268→
269→      // Verify it's this player's turn
270→      const gsRow = findGameState.get(roomId);
271→      const gameState = deserializeGameState(gsRow);
272→
273→      let expectedUserId;
274→      if (gameState.currentTurn === 'white') {
275→        expectedUserId = room.white_user_id;
276→      } else {
277→        expectedUserId = room.black_user_id;
278→      }
279→
280→      if (req.user.id !== expectedUserId) {
281→        return { status: 403, body: { error: 'Not your turn' } };
282→      }
283→
284→      // Check move legality
285→      const legality = isMoveLegal(gameState, parsed.from, parsed.to, parsed.promotion);
286→
287→      if (!legality.legal) {
288→        // Track consecutive illegal moves
289→        const key = getIllegalKey(roomId, req.user.id);
290→        const count = (illegalMoveCounters.get(key) || 0) + 1;
291→        illegalMoveCounters.set(key, count);
292→
293→        if (count >= 3) {
294→          // Forfeit the game
295→          const loser = gameState.currentTurn;
296→          const result = loser === 'white' ? '0-1' : '1-0';
297→          updateRoomResult.run(result, roomId);
298→          illegalMoveCounters.delete(key);
299→
300→          broadcast(roomId, 'gameOver', { result, reason: 'illegal_move_forfeit' });
301→
302→          return {
303→            status: 400,
304→            body: {
305→              error: legality.reason,
306→              forfeit: true,
307→              result,
308→              reason: 'Too many consecutive illegal moves (3)'
309→            }
310→          };
311→        }
312→
313→        const legalMoves = getLegalMoves(gameState);
314→        return {
315→          status: 400,
316→          body: {
317→            error: legality.reason,
318→            illegalMoveCount: count,
319→            legalMoves
320→          }
321→        };
322→      }
323→
324→      // Reset illegal move counter on legal move
325→      const key = getIllegalKey(roomId, req.user.id);
326→      illegalMoveCounters.delete(key);
327→
328→      // Apply the move
329→      const newGameState = applyMove(gameState, parsed.from, parsed.to, parsed.promotion);
330→
331→      // Check game result
332→      const gameResult = getGameResult(newGameState);
333→
334→      // Persist to SQLite
335→      const s = serializeGameState(newGameState);
336→      updateGameState.run(s.board, s.current_turn, s.move_history, s.en_passant_target, s.moved_pieces, s.half_move_clock, s.position_history, roomId);
337→
338→      if (gameResult.over) {
339→        updateRoomResult.run(gameResult.result, roomId);
340→      }
341→
342→      const fen = boardToFEN(newGameState);
343→
344→      return {
345→        status: 200,
346→        body: {
347→          ok: true,
348→          fen,
349→          move: move,
350→          gameOver: gameResult.over,
351→          result: gameResult.over ? gameResult.result : undefined,
352→          reason: gameResult.over ? gameResult.reason : undefined
353→        },
354→        newGameState,
355→        gameResult,
356→        room
357→      };
358→    });
359→
360→    const txResult = submitMove();
361→    res.status(txResult.status).json(txResult.body);
362→
363→    // Post-transaction side effects
364→    if (txResult.status === 200) {
365→      // Broadcast move
366→      broadcast(roomId, 'move', {
367→        move,
368→        fen: txResult.body.fen,
369→        currentTurn: txResult.newGameState.currentTurn,
370→        moveHistory: txResult.newGameState.moveHistory
371→      }, req.user.id);
372→
373→      if (txResult.gameResult.over) {
374→        broadcast(roomId, 'gameOver', {
375→          result: txResult.gameResult.result,
376→          reason: txResult.gameResult.reason
377→        });
378→      }
379→
380→      // If AvE and now Stockfish's turn, trigger async Stockfish move
381→      if (!txResult.gameResult.over && txResult.room.is_stockfish) {
382→        const sfUserId = getOrCreateStockfishUser();
383→        const nextTurn = txResult.newGameState.currentTurn;
384→        const nextUserId = nextTurn === 'white' ? txResult.room.white_user_id : txResult.room.black_user_id;
385→        if (nextUserId === sfUserId) {
386→          triggerStockfishMove(roomId);
387→        }
388→      }
389→    }
390→  });
391→
392→  // Async Stockfish move
393→  function triggerStockfishMove(roomId) {
394→    setTimeout(async () => {
395→      try {
396→        const sfPlayer = getStockfishPlayer();
397→        if (!sfPlayer) return;
398→
399→        const room = findRoomById.get(roomId);
400→        if (!room || room.status !== 'playing') return;
401→
402→        const gsRow = findGameState.get(roomId);
403→        const gameState = deserializeGameState(gsRow);
404→        const fen = boardToFEN(gameState);
405→
406→        const bestMove = await sfPlayer.getBestMove(fen, room.stockfish_level);
407→        if (!bestMove) return;
408→
409→        const moveStr = bestMove.from + bestMove.to + (bestMove.promotion || '');
410→
411→        // Apply Stockfish's move within a transaction
412→        const sfSubmit = db.transaction(() => {
413→          // Re-read to avoid stale state
414→          const freshGsRow = findGameState.get(roomId);
415→          const freshGameState = deserializeGameState(freshGsRow);
416→
417→          const parsed = parseMove(moveStr);
418→          if (!parsed) return null;
419→
420→          const legality = isMoveLegal(freshGameState, parsed.from, parsed.to, parsed.promotion);
421→          if (!legality.legal) {
422→            console.error(`Stockfish made illegal move: ${moveStr} — ${legality.reason}`);
423→            return null;
424→          }
425→
426→          const newGameState = applyMove(freshGameState, parsed.from, parsed.to, parsed.promotion);
427→          const gameResult = getGameResult(newGameState);
428→
429→          const s = serializeGameState(newGameState);
430→          updateGameState.run(s.board, s.current_turn, s.move_history, s.en_passant_target, s.moved_pieces, s.half_move_clock, s.position_history, roomId);
431→
432→          if (gameResult.over) {
433→            updateRoomResult.run(gameResult.result, roomId);
434→          }
435→
436→          return { newGameState, gameResult, moveStr };
437→        });
438→
439→        const result = sfSubmit();
440→        if (!result) return;
441→
442→        const newFen = boardToFEN(result.newGameState);
443→
444→        broadcast(roomId, 'move', {
445→          move: result.moveStr,
446→          fen: newFen,
447→          currentTurn: result.newGameState.currentTurn,
448→          moveHistory: result.newGameState.moveHistory
449→        });
450→
451→        if (result.gameResult.over) {
452→          broadcast(roomId, 'gameOver', {
453→            result: result.gameResult.result,
454→            reason: result.gameResult.reason
455→          });
456→        }
457→      } catch (err) {
458→        console.error('Stockfish move error:', err);
459→      }
460→    }, 100); // Small delay to let the HTTP response complete first
461→  }
462→
463→  return router;
464→}
