 15→// --- Algebraic notation conversion (ported from chessEngine.js) ---
 16→
 17→function indexToAlgebraic(index) {
 18→  const { row, col } = indexToRowCol(index);
 19→  const file = String.fromCharCode(97 + col); // 'a' to 'h'
 20→  const rank = 8 - row;
 21→  return file + rank;
 22→}
 23→
 24→function algebraicToIndex(alg) {
 25→  const col = alg.charCodeAt(0) - 97; // 'a' = 0
 26→  const rank = parseInt(alg[1]);
 27→  const row = 8 - rank;
 28→  return rowColToIndex(row, col);
 29→}
 30→
 31→// --- FEN generation (ported from chessEngine.js) ---
 32→
 33→function boardToFEN(gameState) {
 34→  const { board, currentTurn, halfMoveClock, enPassantTarget, movedPieces } = gameState;
 35→  let fen = '';
 36→
 37→  // Piece placement
 38→  for (let row = 0; row < 8; row++) {
 39→    let emptyCount = 0;
 40→    for (let col = 0; col < 8; col++) {
 41→      const piece = board[row * 8 + col];
 42→      if (piece === 0) {
 43→        emptyCount++;
 44→      } else {
 45→        if (emptyCount > 0) {
 46→          fen += emptyCount;
 47→          emptyCount = 0;
 48→        }
 49→        fen += PIECE_TO_FEN[piece] || '?';
 50→      }
 51→    }
 52→    if (emptyCount > 0) {
 53→      fen += emptyCount;
 54→    }
 55→    if (row < 7) fen += '/';
 56→  }
 57→
 58→  // Active color
 59→  fen += ' ' + (currentTurn === COLORS.WHITE ? 'w' : 'b');
 60→
 61→  // Castling availability
 62→  let castling = '';
 63→  // White kingside: king on e1 (60) and rook on h1 (63) haven't moved
 64→  if (!movedPieces.has(60) && !movedPieces.has(63) && board[60] === PIECE_TYPES.KING && board[63] === PIECE_TYPES.ROOK) castling += 'K';
 65→  // White queenside: king on e1 (60) and rook on a1 (56) haven't moved
 66→  if (!movedPieces.has(60) && !movedPieces.has(56) && board[60] === PIECE_TYPES.KING && board[56] === PIECE_TYPES.ROOK) castling += 'Q';
 67→  // Black kingside: king on e8 (4) and rook on h8 (7) haven't moved
 68→  if (!movedPieces.has(4) && !movedPieces.has(7) && board[4] === -PIECE_TYPES.KING && board[7] === -PIECE_TYPES.ROOK) castling += 'k';
 69→  // Black queenside: king on e8 (4) and rook on a8 (0) haven't moved
 70→  if (!movedPieces.has(4) && !movedPieces.has(0) && board[4] === -PIECE_TYPES.KING && board[0] === -PIECE_TYPES.ROOK) castling += 'q';
 71→  fen += ' ' + (castling || '-');
 72→
 73→  // En passant target
 74→  fen += ' ' + (enPassantTarget !== null ? indexToAlgebraic(enPassantTarget) : '-');
 75→
 76→  // Halfmove clock
 77→  fen += ' ' + halfMoveClock;
 78→
 79→  // Fullmove number (derive from move history length)
 80→  const fullMove = Math.floor((gameState.moveHistory || []).length / 2) + 1;
 81→  fen += ' ' + fullMove;
 82→
 83→  return fen;
 84→}
