 86→// --- Move parsing ---
 87→
 88→function parseMove(moveStr) {
 89→  if (!moveStr || typeof moveStr !== 'string') return null;
 90→
 91→  // Normalize: remove spaces, dashes, lowercase
 92→  const clean = moveStr.replace(/[\s\-]/g, '').toLowerCase();
 93→
 94→  // UCI format: e2e4, e7e8q (with optional promotion)
 95→  const uciMatch = clean.match(/^([a-h][1-8])([a-h][1-8])([qrbn])?$/);
 96→  if (uciMatch) {
 97→    return {
 98→      from: algebraicToIndex(uciMatch[1]),
 99→      to: algebraicToIndex(uciMatch[2]),
100→      promotion: uciMatch[3] || null
101→    };
102→  }
103→
104→  return null;
105→}
106→
107→// --- Move legality check ---
108→
109→function isMoveLegal(gameState, from, to, promotion) {
110→  const { board, currentTurn, enPassantTarget, movedPieces } = gameState;
111→  const piece = board[from];
112→
113→  // Must have a piece at source
114→  if (piece === 0) {
115→    return { legal: false, reason: 'No piece at source square' };
116→  }
117→
118→  // Must be the correct color's turn
119→  const pieceColor = getPieceColor(piece);
120→  if (pieceColor !== currentTurn) {
121→    return { legal: false, reason: 'Not your piece' };
122→  }
123→
124→  // Can't capture own piece
125→  const targetPiece = board[to];
126→  if (targetPiece !== 0 && getPieceColor(targetPiece) === currentTurn) {
127→    return { legal: false, reason: 'Cannot capture your own piece' };
128→  }
129→
130→  const pieceType = Math.abs(piece);
131→  let isValid = false;
132→
133→  // Dispatch to piece-specific validation
134→  switch (pieceType) {
135→    case PIECE_TYPES.PAWN:
136→      isValid = isValidPawnMove(board, from, to, enPassantTarget);
137→      break;
138→    case PIECE_TYPES.KNIGHT:
139→      isValid = isValidKnightMove(board, from, to);
140→      break;
141→    case PIECE_TYPES.BISHOP:
142→      isValid = isValidBishopMove(board, from, to);
143→      break;
144→    case PIECE_TYPES.ROOK:
145→      isValid = isValidRookMove(board, from, to);
146→      break;
147→    case PIECE_TYPES.QUEEN:
148→      isValid = isValidQueenMove(board, from, to);
149→      break;
150→    case PIECE_TYPES.KING: {
151→      // For castling, check if king has moved AND if rook has moved
152→      const kingHasMoved = movedPieces.has(from);
153→      const { row: fromRow, col: fromCol } = indexToRowCol(from);
154→      const { col: toCol } = indexToRowCol(to);
155→      const colDiff = Math.abs(toCol - fromCol);
156→
157→      if (colDiff === 2 && !kingHasMoved) {
158→        // Castling attempt - also need to check rook hasn't moved
159→        const direction = toCol > fromCol ? 1 : -1;
160→        const rookCol = direction === 1 ? 7 : 0;
161→        const rookIndex = rowColToIndex(fromRow, rookCol);
162→        if (movedPieces.has(rookIndex)) {
163→          return { legal: false, reason: 'Rook has already moved' };
164→        }
165→      }
166→
167→      isValid = isValidKingMove(board, from, to, kingHasMoved);
168→      break;
169→    }
170→  }
171→
172→  if (!isValid) {
173→    return { legal: false, reason: 'Invalid move for this piece' };
174→  }
175→
176→  // Simulate move and check if own king is in check
177→  const testBoard = [...board];
178→  testBoard[to] = piece;
179→  testBoard[from] = 0;
180→
181→  // Handle en passant capture in simulation
182→  if (pieceType === PIECE_TYPES.PAWN && to === enPassantTarget) {
183→    const { row: toRow, col: toCol } = indexToRowCol(to);
184→    const capturedPawnRow = isWhitePiece(piece) ? toRow + 1 : toRow - 1;
185→    testBoard[rowColToIndex(capturedPawnRow, toCol)] = 0;
186→  }
187→
188→  const isWhite = currentTurn === COLORS.WHITE;
189→  if (isKingInCheck(testBoard, isWhite)) {
190→    return { legal: false, reason: 'Move would leave king in check' };
191→  }
192→
193→  // Check promotion requirements
194→  if (needsPromotion(piece, to)) {
195→    if (!promotion) {
196→      return { legal: false, reason: 'Promotion piece required (q, r, b, n)' };
197→    }
198→    const validPromotions = ['q', 'r', 'b', 'n'];
199→    if (!validPromotions.includes(promotion)) {
200→      return { legal: false, reason: 'Invalid promotion piece. Must be q, r, b, or n' };
201→    }
202→  }
203→
204→  return { legal: true };
205→}
