207→// --- Generate all legal moves ---
208→
209→function getLegalMoves(gameState) {
210→  const { board, currentTurn } = gameState;
211→  const isWhite = currentTurn === COLORS.WHITE;
212→  const moves = [];
213→
214→  for (let from = 0; from < 64; from++) {
215→    const piece = board[from];
216→    if (piece === 0) continue;
217→    if (isWhite && !isWhitePiece(piece)) continue;
218→    if (!isWhite && !isBlackPiece(piece)) continue;
219→
220→    for (let to = 0; to < 64; to++) {
221→      if (from === to) continue;
222→
223→      // For pawn promotions, try queen promotion as default check
224→      const pieceType = Math.abs(piece);
225→      let promotion = null;
226→      if (pieceType === PIECE_TYPES.PAWN && needsPromotion(piece, to)) {
227→        promotion = 'q'; // Check with queen; other promotions are also legal
228→      }
229→
230→      const result = isMoveLegal(gameState, from, to, promotion);
231→      if (result.legal) {
232→        const uci = indexToAlgebraic(from) + indexToAlgebraic(to);
233→        if (pieceType === PIECE_TYPES.PAWN && needsPromotion(piece, to)) {
234→          // Add all promotion variants
235→          moves.push(uci + 'q');
236→          moves.push(uci + 'r');
237→          moves.push(uci + 'b');
238→          moves.push(uci + 'n');
239→        } else {
240→          moves.push(uci);
241→        }
242→      }
243→    }
244→  }
245→
246→  return moves;
247→}
