249→// --- Apply a move to game state (mutates a copy) ---
250→
251→function applyMove(gameState, from, to, promotion) {
252→  const board = [...gameState.board];
253→  const piece = board[from];
254→  const pieceType = Math.abs(piece);
255→  const isWhite = isWhitePiece(piece);
256→  let isCapture = board[to] !== 0;
257→
258→  // Basic move
259→  board[to] = piece;
260→  board[from] = 0;
261→
262→  // Castling: move the rook too
263→  if (pieceType === PIECE_TYPES.KING) {
264→    const { row: fromRow, col: fromCol } = indexToRowCol(from);
265→    const { col: toCol } = indexToRowCol(to);
266→    if (Math.abs(toCol - fromCol) === 2) {
267→      const direction = toCol > fromCol ? 1 : -1;
268→      const rookCol = direction === 1 ? 7 : 0;
269→      const rookIndex = rowColToIndex(fromRow, rookCol);
270→      const newRookIndex = rowColToIndex(fromRow, toCol - direction);
271→      board[newRookIndex] = board[rookIndex];
272→      board[rookIndex] = 0;
273→    }
274→  }
275→
276→  // En passant capture: remove the captured pawn
277→  if (pieceType === PIECE_TYPES.PAWN && to === gameState.enPassantTarget) {
278→    const { row: toRow, col: toCol } = indexToRowCol(to);
279→    const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
280→    board[rowColToIndex(capturedPawnRow, toCol)] = 0;
281→    isCapture = true;
282→  }
283→
284→  // Promotion
285→  if (pieceType === PIECE_TYPES.PAWN && needsPromotion(piece, to)) {
286→    const promotionMap = {
287→      'q': PIECE_TYPES.QUEEN,
288→      'r': PIECE_TYPES.ROOK,
289→      'b': PIECE_TYPES.BISHOP,
290→      'n': PIECE_TYPES.KNIGHT
291→    };
292→    const promotedType = promotionMap[promotion] || PIECE_TYPES.QUEEN;
293→    board[to] = isWhite ? promotedType : -promotedType;
294→  }
295→
296→  // Update en passant target
297→  const newEnPassantTarget = getEnPassantTarget(gameState.board, from, to);
298→
299→  // Update moved pieces
300→  const newMovedPieces = new Set(gameState.movedPieces);
301→  newMovedPieces.add(from);
302→
303→  // Update half-move clock
304→  const newHalfMoveClock = (pieceType === PIECE_TYPES.PAWN || isCapture) ? 0 : gameState.halfMoveClock + 1;
305→
306→  // Update position history
307→  const positionKey = generatePositionKey(board);
308→  const newPositionHistory = [...gameState.positionHistory, positionKey];
309→
310→  // Update move history
311→  const moveUci = indexToAlgebraic(from) + indexToAlgebraic(to) + (promotion || '');
312→  const newMoveHistory = [...gameState.moveHistory, moveUci];
313→
314→  // Toggle turn
315→  const nextTurn = gameState.currentTurn === COLORS.WHITE ? COLORS.BLACK : COLORS.WHITE;
316→
317→  return {
318→    board,
319→    currentTurn: nextTurn,
320→    moveHistory: newMoveHistory,
321→    enPassantTarget: newEnPassantTarget,
322→    movedPieces: newMovedPieces,
323→    halfMoveClock: newHalfMoveClock,
324→    positionHistory: newPositionHistory
325→  };
326→}
327→
328→// --- Game result detection (fixes stalemate bug) ---
329→
330→function getGameResult(gameState) {
331→  const { board, currentTurn, halfMoveClock, positionHistory } = gameState;
332→  const isWhite = currentTurn === COLORS.WHITE;
333→
334→  // Check for insufficient material
335→  if (isInsufficientMaterial(board)) {
336→    return { over: true, result: '1/2-1/2', reason: 'insufficient_material' };
337→  }
338→
339→  // 50-move rule (100 half-moves)
340→  if (halfMoveClock >= 100) {
341→    return { over: true, result: '1/2-1/2', reason: 'fifty_move_rule' };
342→  }
343→
344→  // Threefold repetition
345→  const currentPosition = generatePositionKey(board);
346→  const repetitions = positionHistory.filter(p => p === currentPosition).length;
347→  if (repetitions >= 3) {
348→    return { over: true, result: '1/2-1/2', reason: 'threefold_repetition' };
349→  }
350→
351→  // Check legal moves for the side to move
352→  const legalMoves = getLegalMoves(gameState);
353→
354→  if (legalMoves.length === 0) {
355→    // No legal moves — is the king in check?
356→    if (isKingInCheck(board, isWhite)) {
357→      // Checkmate: the other side wins
358→      const winner = isWhite ? '0-1' : '1-0';
359→      return { over: true, result: winner, reason: 'checkmate' };
360→    } else {
361→      // Stalemate
362→      return { over: true, result: '1/2-1/2', reason: 'stalemate' };
363→    }
364→  }
365→
366→  return { over: false };
367→}
