369→// --- Initial game state ---
370→
371→function createInitialGameState() {
372→  return {
373→    board: [...INITIAL_BOARD],
374→    currentTurn: COLORS.WHITE,
375→    moveHistory: [],
376→    enPassantTarget: null,
377→    movedPieces: new Set(),
378→    halfMoveClock: 0,
379→    positionHistory: []
380→  };
381→}
382→
383→// --- Serialization for SQLite ---
384→
385→function serializeGameState(gs) {
386→  return {
387→    board: JSON.stringify(gs.board),
388→    current_turn: gs.currentTurn,
389→    move_history: JSON.stringify(gs.moveHistory),
390→    en_passant_target: gs.enPassantTarget,
391→    moved_pieces: JSON.stringify([...gs.movedPieces]),
392→    half_move_clock: gs.halfMoveClock,
393→    position_history: JSON.stringify(gs.positionHistory)
394→  };
395→}
396→
397→function deserializeGameState(row) {
398→  return {
399→    board: JSON.parse(row.board),
400→    currentTurn: row.current_turn,
