  3→// Helper to convert index to row/col
  4→const indexToRowCol = (index) => {
  5→  const row = Math.floor(index / 8);
  6→  const col = index % 8;
  7→  return { row, col };
  8→};
  9→
 10→// Helper to convert row/col to index
 11→const rowColToIndex = (row, col) => {
 12→  return row * 8 + col;
 13→};
 14→
 15→// Validate pawn moves
 16→const isValidPawnMove = (board, fromIndex, toIndex, enPassantTarget) => {
 17→  const piece = board[fromIndex];
 18→  const targetPiece = board[toIndex];
 19→  const pieceType = Math.abs(piece);
 20→
 21→  if (pieceType !== PIECE_TYPES.PAWN) {
 22→    return false;
 23→  }
 24→
 25→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
 26→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
 27→
 28→  const isWhite = isWhitePiece(piece);
 29→  const direction = isWhite ? -1 : 1;
 30→  const startingRow = isWhite ? 6 : 1;
 31→
 32→  const rowDiff = toRow - fromRow;
 33→  const colDiff = Math.abs(toCol - fromCol);
 34→
 35→  // 1. Move forward 1 square
 36→  if (rowDiff === direction && colDiff === 0 && targetPiece === 0) {
 37→    return true;
 38→  }
 39→
 40→  // 2. Move forward 2 squares from starting position
 41→  if (
 42→    fromRow === startingRow &&
 43→    rowDiff === direction * 2 &&
 44→    colDiff === 0 &&
 45→    targetPiece === 0
 46→  ) {
 47→    const middleIndex = rowColToIndex(fromRow + direction, fromCol);
 48→    if (board[middleIndex] === 0) {
 49→      return true;
 50→    }
 51→  }
 52→
 53→  // 3. Diagonal capture
 54→  if (rowDiff === direction && colDiff === 1) {
 55→    // Regular capture
 56→    if (targetPiece !== 0) {
 57→      if (isWhite && isBlackPiece(targetPiece)) {
 58→        return true;
 59→      }
 60→      if (!isWhite && isWhitePiece(targetPiece)) {
 61→        return true;
 62→      }
 63→    }
 64→
 65→    // En passant capture
 66→    if (toIndex === enPassantTarget) {
 67→      return true;
 68→    }
 69→  }
 70→
 71→  return false;
 72→};
