 74→// Check if move results in en passant opportunity
 75→const getEnPassantTarget = (board, fromIndex, toIndex) => {
 76→  const piece = board[fromIndex];
 77→  const pieceType = Math.abs(piece);
 78→
 79→  if (pieceType !== PIECE_TYPES.PAWN) {
 80→    return null;
 81→  }
 82→
 83→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
 84→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
 85→
 86→  const isWhite = isWhitePiece(piece);
 87→  const direction = isWhite ? -1 : 1;
 88→
 89→  if (Math.abs(toRow - fromRow) === 2 && fromCol === toCol) {
 90→    return rowColToIndex(toRow - direction, toCol);
 91→  }
 92→
 93→  return null;
 94→};
