 96→// Check if pawn needs promotion
 97→const needsPromotion = (piece, toIndex) => {
 98→  const pieceType = Math.abs(piece);
 99→  if (pieceType !== PIECE_TYPES.PAWN) {
100→    return false;
101→  }
102→
103→  const { row } = indexToRowCol(toIndex);
104→  const isWhite = isWhitePiece(piece);
105→
106→  return (isWhite && row === 0) || (!isWhite && row === 7);
107→};
