109→// Helper to check if path is clear (no pieces in between)
110→const isPathClear = (board, fromIndex, toIndex) => {
111→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
112→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
113→
114→  const rowStep = toRow > fromRow ? 1 : toRow < fromRow ? -1 : 0;
115→  const colStep = toCol > fromCol ? 1 : toCol < fromCol ? -1 : 0;
116→
117→  let currentRow = fromRow + rowStep;
118→  let currentCol = fromCol + colStep;
119→
120→  while (currentRow !== toRow || currentCol !== toCol) {
121→    const index = rowColToIndex(currentRow, currentCol);
122→    if (board[index] !== 0) {
123→      return false;
124→    }
125→    currentRow += rowStep;
126→    currentCol += colStep;
127→  }
128→
129→  return true;
130→};
