132→// Validate rook moves
133→const isValidRookMove = (board, fromIndex, toIndex) => {
134→  const piece = board[fromIndex];
135→  const targetPiece = board[toIndex];
136→  const pieceType = Math.abs(piece);
137→
138→  if (pieceType !== PIECE_TYPES.ROOK) {
139→    return false;
140→  }
141→
142→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
143→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
144→
145→  const isHorizontal = fromRow === toRow && fromCol !== toCol;
146→  const isVertical = fromCol === toCol && fromRow !== toRow;
147→
148→  if (!isHorizontal && !isVertical) {
149→    return false;
150→  }
151→
152→  if (!isPathClear(board, fromIndex, toIndex)) {
153→    return false;
154→  }
155→
156→  if (targetPiece !== 0) {
157→    const isWhite = isWhitePiece(piece);
158→    if (isWhite && isWhitePiece(targetPiece)) {
159→      return false;
160→    }
161→    if (!isWhite && isBlackPiece(targetPiece)) {
162→      return false;
163→    }
164→  }
165→
166→  return true;
167→};
