169→// Validate bishop moves
170→const isValidBishopMove = (board, fromIndex, toIndex) => {
171→  const piece = board[fromIndex];
172→  const targetPiece = board[toIndex];
173→  const pieceType = Math.abs(piece);
174→
175→  if (pieceType !== PIECE_TYPES.BISHOP) {
176→    return false;
177→  }
178→
179→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
180→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
181→
182→  const rowDiff = Math.abs(toRow - fromRow);
183→  const colDiff = Math.abs(toCol - fromCol);
184→
185→  if (rowDiff !== colDiff || rowDiff === 0) {
186→    return false;
187→  }
188→
189→  if (!isPathClear(board, fromIndex, toIndex)) {
190→    return false;
191→  }
192→
193→  if (targetPiece !== 0) {
194→    const isWhite = isWhitePiece(piece);
195→    if (isWhite && isWhitePiece(targetPiece)) {
196→      return false;
197→    }
198→    if (!isWhite && isBlackPiece(targetPiece)) {
199→      return false;
200→    }
201→  }
202→
203→  return true;
204→};
