206→// Helper function to check if a square is under attack by opponent
207→const isSquareUnderAttack = (board, squareIndex, byColor) => {
208→  const { row: targetRow, col: targetCol } = indexToRowCol(squareIndex);
209→
210→  for (let i = 0; i < 64; i++) {
211→    const piece = board[i];
212→    if (piece === 0) continue;
213→
214→    const pieceIsWhite = isWhitePiece(piece);
215→    const pieceColor = pieceIsWhite ? 'white' : 'black';
216→
217→    if (pieceColor !== byColor) continue;
218→
219→    const pieceType = Math.abs(piece);
220→
221→    switch (pieceType) {
222→      case PIECE_TYPES.PAWN: {
223→        const { row: fromRow, col: fromCol } = indexToRowCol(i);
224→        const direction = pieceIsWhite ? -1 : 1;
225→        if (fromRow + direction === targetRow && Math.abs(fromCol - targetCol) === 1) {
226→          return true;
227→        }
228→        break;
229→      }
230→      case PIECE_TYPES.KNIGHT:
231→        if (isValidKnightMove(board, i, squareIndex)) {
232→          return true;
233→        }
234→        break;
235→      case PIECE_TYPES.BISHOP:
236→        if (isValidBishopMove(board, i, squareIndex)) {
237→          return true;
238→        }
239→        break;
240→      case PIECE_TYPES.ROOK:
241→        if (isValidRookMove(board, i, squareIndex)) {
242→          return true;
243→        }
244→        break;
245→      case PIECE_TYPES.QUEEN:
246→        if (isValidQueenMove(board, i, squareIndex)) {
247→          return true;
248→        }
249→        break;
250→      case PIECE_TYPES.KING: {
251→        const { row: fromRow, col: fromCol } = indexToRowCol(i);
252→        if (Math.abs(fromRow - targetRow) <= 1 && Math.abs(fromCol - targetCol) <= 1) {
253→          return true;
254→        }
255→        break;
256→      }
257→    }
258→  }
259→
260→  return false;
261→};
