263→// Find the king's position on the board
264→const findKing = (board, isWhite) => {
265→  const kingValue = isWhite ? PIECE_TYPES.KING : -PIECE_TYPES.KING;
266→  for (let i = 0; i < 64; i++) {
267→    if (board[i] === kingValue) {
268→      return i;
269→    }
270→  }
271→  return null;
272→};
