274→// Check if the king is in check
275→const isKingInCheck = (board, isWhite) => {
276→  const kingIndex = findKing(board, isWhite);
277→  if (kingIndex === null) return false;
278→
279→  const opponentColor = isWhite ? 'black' : 'white';
280→  return isSquareUnderAttack(board, kingIndex, opponentColor);
281→};
