283→// Validate king moves
284→const isValidKingMove = (board, fromIndex, toIndex, hasMoved) => {
285→  const piece = board[fromIndex];
286→  const targetPiece = board[toIndex];
287→  const pieceType = Math.abs(piece);
288→
289→  if (pieceType !== PIECE_TYPES.KING) {
290→    return false;
291→  }
292→
293→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
294→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
295→
296→  const rowDiff = Math.abs(toRow - fromRow);
297→  const colDiff = Math.abs(toCol - fromCol);
298→
299→  const isWhite = isWhitePiece(piece);
300→
301→  // Basic king move: 1 square in any direction
302→  if (rowDiff <= 1 && colDiff <= 1 && (rowDiff + colDiff > 0)) {
303→    if (targetPiece !== 0) {
304→      if (isWhite && isWhitePiece(targetPiece)) {
305→        return false;
306→      }
307→      if (!isWhite && isBlackPiece(targetPiece)) {
308→        return false;
309→      }
310→    }
311→
312→    const testBoard = [...board];
313→    testBoard[toIndex] = piece;
314→    testBoard[fromIndex] = 0;
315→
316→    if (isKingInCheck(testBoard, isWhite)) {
317→      return false;
318→    }
319→
320→    return true;
321→  }
322→
323→  // Castling: king moves 2 squares horizontally
324→  if (rowDiff === 0 && colDiff === 2 && !hasMoved) {
325→    const direction = toCol > fromCol ? 1 : -1;
326→    const rookCol = direction === 1 ? 7 : 0;
327→    const rookIndex = rowColToIndex(fromRow, rookCol);
328→    const rook = board[rookIndex];
329→
330→    const expectedRook = isWhite ? PIECE_TYPES.ROOK : -PIECE_TYPES.ROOK;
331→    if (rook !== expectedRook) {
332→      return false;
333→    }
334→
335→    if (isKingInCheck(board, isWhite)) {
336→      return false;
337→    }
338→
339→    const start = Math.min(fromCol, rookCol) + 1;
340→    const end = Math.max(fromCol, rookCol);
341→    for (let col = start; col < end; col++) {
342→      const index = rowColToIndex(fromRow, col);
343→      if (board[index] !== 0) {
344→        return false;
345→      }
346→    }
347→
348→    for (let col = fromCol; col !== toCol + direction; col += direction) {
349→      const index = rowColToIndex(fromRow, col);
350→      const testBoard = [...board];
351→      testBoard[index] = piece;
352→      testBoard[fromIndex] = 0;
353→
354→      const opponentColor = isWhite ? 'black' : 'white';
355→      if (isSquareUnderAttack(testBoard, index, opponentColor)) {
356→        return false;
357→      }
358→    }
359→
360→    return true;
361→  }
362→
363→  return false;
364→};
365→
366→// Validate queen moves
367→const isValidQueenMove = (board, fromIndex, toIndex) => {
368→  const piece = board[fromIndex];
369→  const pieceType = Math.abs(piece);
370→
371→  if (pieceType !== PIECE_TYPES.QUEEN) {
372→    return false;
373→  }
374→
375→  const tempRook = piece > 0 ? PIECE_TYPES.ROOK : -PIECE_TYPES.ROOK;
376→  const tempBishop = piece > 0 ? PIECE_TYPES.BISHOP : -PIECE_TYPES.BISHOP;
377→
378→  const tempBoard = [...board];
379→
380→  tempBoard[fromIndex] = tempRook;
381→  if (isValidRookMove(tempBoard, fromIndex, toIndex)) {
382→    return true;
383→  }
384→
385→  tempBoard[fromIndex] = tempBishop;
386→  if (isValidBishopMove(tempBoard, fromIndex, toIndex)) {
387→    return true;
388→  }
389→
390→  return false;
391→};
392→
393→// Validate knight moves
394→const isValidKnightMove = (board, fromIndex, toIndex) => {
395→  const piece = board[fromIndex];
396→  const targetPiece = board[toIndex];
397→  const pieceType = Math.abs(piece);
398→
399→  if (pieceType !== PIECE_TYPES.KNIGHT) {
400→    return false;
401→  }
402→
403→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
404→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
405→
406→  const rowDiff = Math.abs(toRow - fromRow);
407→  const colDiff = Math.abs(toCol - fromCol);
408→
409→  const isLShape = (rowDiff === 2 && colDiff === 1) || (rowDiff === 1 && colDiff === 2);
410→
411→  if (!isLShape) {
412→    return false;
413→  }
414→
415→  if (targetPiece !== 0) {
416→    const isWhite = isWhitePiece(piece);
417→    if (isWhite && isWhitePiece(targetPiece)) {
418→      return false;
419→    }
420→    if (!isWhite && isBlackPiece(targetPiece)) {
421→      return false;
422→    }
423→  }
424→
425→  return true;
426→};
427→
428→// Check if checkmate
429→const isCheckmate = (board, isWhite) => {
430→  const inCheck = isKingInCheck(board, isWhite);
431→
432→  for (let fromIndex = 0; fromIndex < 64; fromIndex++) {
433→    const piece = board[fromIndex];
434→    if (piece === 0) continue;
435→
436→    const pieceIsWhite = isWhitePiece(piece);
437→    if (pieceIsWhite !== isWhite) continue;
438→
439→    const pieceType = Math.abs(piece);
440→
441→    for (let toIndex = 0; toIndex < 64; toIndex++) {
442→      if (fromIndex === toIndex) continue;
443→
444→      let isValid = false;
445→
446→      switch (pieceType) {
447→        case PIECE_TYPES.PAWN:
448→          isValid = isValidPawnMove(board, fromIndex, toIndex, null);
449→          break;
450→        case PIECE_TYPES.KNIGHT:
451→          isValid = isValidKnightMove(board, fromIndex, toIndex);
452→          break;
453→        case PIECE_TYPES.BISHOP:
454→          isValid = isValidBishopMove(board, fromIndex, toIndex);
455→          break;
456→        case PIECE_TYPES.ROOK:
457→          isValid = isValidRookMove(board, fromIndex, toIndex);
458→          break;
459→        case PIECE_TYPES.QUEEN:
460→          isValid = isValidQueenMove(board, fromIndex, toIndex);
461→          break;
462→        case PIECE_TYPES.KING:
463→          isValid = isValidKingMove(board, fromIndex, toIndex, false);
464→          break;
465→      }
466→
467→      if (isValid) {
468→        const testBoard = [...board];
469→        testBoard[toIndex] = piece;
470→        testBoard[fromIndex] = 0;
471→
472→        if (!isKingInCheck(testBoard, isWhite)) {
473→          return false;
474→        }
475→      }
476→    }
477→  }
478→
479→  return inCheck;
480→};
