482→// Check for insufficient material (automatic draw)
483→const isInsufficientMaterial = (board) => {
484→  const pieces = [];
485→
486→  for (let i = 0; i < 64; i++) {
487→    if (board[i] !== 0) {
488→      pieces.push(Math.abs(board[i]));
489→    }
490→  }
491→
492→  // King vs King
493→  if (pieces.length === 2) {
494→    return true;
495→  }
496→
497→  // King + minor piece vs King
498→  if (pieces.length === 3) {
499→    const nonKings = pieces.filter(p => p !== PIECE_TYPES.KING);
500→    if (nonKings.every(p => p === PIECE_TYPES.BISHOP || p === PIECE_TYPES.KNIGHT)) {
501→      return true;
502→    }
503→  }
504→
505→  // King + Bishop vs King + Bishop (same color squares)
506→  if (pieces.length === 4) {
507→    const bishops = [];
508→    for (let i = 0; i < 64; i++) {
509→      if (Math.abs(board[i]) === PIECE_TYPES.BISHOP) {
510→        const { row, col } = indexToRowCol(i);
511→        bishops.push((row + col) % 2);
512→      }
513→    }
514→    if (bishops.length === 2 && bishops[0] === bishops[1]) {
515→      return true;
516→    }
517→  }
518→
519→  return false;
520→};
