 56→// Standard starting position in FEN notation
 57→const STARTING_FEN = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR';
 58→
 59→// FEN character to piece number mapping
 60→const FEN_TO_PIECE = {
 61→  'K': 1,   // White King
 62→  'P': 2,   // White Pawn
 63→  'N': 3,   // White Knight
 64→  'R': 4,   // White Rook
 65→  'B': 5,   // White Bishop
 66→  'Q': 6,   // White Queen
 67→  'k': -1,  // Black King
 68→  'p': -2,  // Black Pawn
 69→  'n': -3,  // Black Knight
 70→  'r': -4,  // Black Rook
 71→  'b': -5,  // Black Bishop
 72→  'q': -6,  // Black Queen
 73→};
 74→
 75→// Piece number to FEN character mapping (reverse of FEN_TO_PIECE)
 76→const PIECE_TO_FEN = {};
 77→for (const [char, num] of Object.entries(FEN_TO_PIECE)) {
 78→  PIECE_TO_FEN[num] = char;
 79→}
