 81→// Parse FEN notation to board array
 82→const parseFEN = (fen) => {
 83→  const board = new Array(64).fill(0);
 84→  const ranks = fen.split('/');
 85→
 86→  let squareIndex = 0;
 87→
 88→  for (let rank of ranks) {
 89→    for (let char of rank) {
 90→      if (isNaN(char)) {
 91→        board[squareIndex] = FEN_TO_PIECE[char];
 92→        squareIndex++;
 93→      } else {
 94→        const emptySquares = parseInt(char);
 95→        squareIndex += emptySquares;
 96→      }
 97→    }
 98→  }
 99→
100→  return board;
101→};
