const { WebSocketServer } = require('ws');
const url = require('url');

function setupWebSocket(server, db) {
  const wss = new WebSocketServer({ noServer: true });

  // Track clients per room: Map<roomId, Set<{ ws, userId, username, role }>>
  const rooms = new Map();

  const findUserByToken = db.prepare('SELECT id, username FROM users WHERE token = ?');
  const findRoom = db.prepare('SELECT * FROM rooms WHERE id = ?');

  // Handle HTTP upgrade
  server.on('upgrade', (request, socket, head) => {
    const parsed = url.parse(request.url, true);
    const pathname = parsed.pathname;

    // Match /api/rooms/:id/ws
    const match = pathname.match(/^\/api\/rooms\/(\d+)\/ws$/);
    if (!match) {
      socket.destroy();
      return;
    }

    const roomId = parseInt(match[1]);
    const token = parsed.query.token;

    if (!token) {
      socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
      socket.destroy();
      return;
    }

    const user = findUserByToken.get(token);
    if (!user) {
      socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
      socket.destroy();
      return;
    }

    const room = findRoom.get(roomId);
    if (!room) {
      socket.write('HTTP/1.1 404 Not Found\r\n\r\n');
      socket.destroy();
      return;
    }

    // Determine role
    let role = 'spectator';
    if (user.id === room.white_user_id || user.id === room.black_user_id) {
      role = 'player';
    }

    wss.handleUpgrade(request, socket, head, (ws) => {
      wss.emit('connection', ws, { roomId, user, role });
    });
  });

  // Handle new connections
  wss.on('connection', (ws, { roomId, user, role }) => {
    // Add to room tracking
    if (!rooms.has(roomId)) {
      rooms.set(roomId, new Set());
    }

    const client = { ws, userId: user.id, username: user.username, role };
    rooms.get(roomId).add(client);

    // Send joined confirmation to the new client
    ws.send(JSON.stringify({
      event: 'joined',
      data: {
        roomId,
        userId: user.id,
        username: user.username,
        role
      }
    }));

    // Notify others in the room
    broadcast(roomId, 'playerConnected', {
      userId: user.id,
      username: user.username,
      role
    }, user.id);

    // Handle disconnect
    ws.on('close', () => {
      const roomClients = rooms.get(roomId);
      if (roomClients) {
        roomClients.delete(client);
        if (roomClients.size === 0) {
          rooms.delete(roomId);
        }
      }

      broadcast(roomId, 'playerDisconnected', {
        userId: user.id,
        username: user.username
      });
    });

    // Handle errors
    ws.on('error', (err) => {
      console.error(`WebSocket error for user ${user.id} in room ${roomId}:`, err.message);
    });
  });

  // Broadcast to all clients in a room, optionally excluding a user
  function broadcast(roomId, event, data, excludeUserId) {
    const roomClients = rooms.get(roomId);
    if (!roomClients) return;

    const message = JSON.stringify({ event, data });

    for (const client of roomClients) {
      if (excludeUserId && client.userId === excludeUserId) continue;
      if (client.ws.readyState === 1) { // WebSocket.OPEN
        client.ws.send(message);
      }
    }
  }

  return { broadcast };
}

module.exports = { setupWebSocket };

const Database = require('better-sqlite3');
const path = require('path');

const DB_PATH = path.join(__dirname, 'chess.db');

function createDb() {
  const db = new Database(DB_PATH);

  // Enable WAL mode for better concurrent read performance
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');

  // Create tables
  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      token TEXT UNIQUE NOT NULL,
      passkey_address TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS rooms (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      invite_code TEXT UNIQUE NOT NULL,
      white_user_id INTEGER REFERENCES users(id),
      black_user_id INTEGER REFERENCES users(id),
      status TEXT NOT NULL DEFAULT 'waiting',
      is_stockfish INTEGER NOT NULL DEFAULT 0,
      stockfish_level INTEGER DEFAULT NULL,
      result TEXT DEFAULT NULL,
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS game_states (
      room_id INTEGER PRIMARY KEY REFERENCES rooms(id),
      board TEXT NOT NULL,
      current_turn TEXT NOT NULL DEFAULT 'white',
      move_history TEXT NOT NULL DEFAULT '[]',
      en_passant_target INTEGER DEFAULT NULL,
      moved_pieces TEXT NOT NULL DEFAULT '[]',
      half_move_clock INTEGER NOT NULL DEFAULT 0,
      position_history TEXT NOT NULL DEFAULT '[]',
      updated_at TEXT DEFAULT (datetime('now'))
    );

    CREATE INDEX IF NOT EXISTS idx_rooms_invite_code ON rooms(invite_code);
    CREATE INDEX IF NOT EXISTS idx_users_token ON users(token);
  `);

  return db;
}

module.exports = { createDb };

