  1→const { spawn } = require('child_process');
  2→
  3→class StockfishPlayer {
  4→  constructor() {
  5→    this.process = null;
  6→    this.ready = false;
  7→  }
  8→
  9→  async init() {
 10→    return new Promise((resolve, reject) => {
 11→      try {
 12→        this.process = spawn('stockfish');
 13→      } catch (err) {
 14→        reject(new Error('Stockfish binary not found'));
 15→        return;
 16→      }
 17→
 18→      this.process.on('error', (err) => {
 19→        console.error('Stockfish process error:', err.message);
 20→        this.ready = false;
 21→        reject(err);
 22→      });
 23→
 24→      let initBuffer = '';
 25→      const onData = (data) => {
 26→        initBuffer += data.toString();
 27→        if (initBuffer.includes('readyok')) {
 28→          this.process.stdout.removeListener('data', onData);
 29→          this.ready = true;
 30→          resolve();
 31→        }
 32→      };
 33→
 34→      this.process.stdout.on('data', onData);
 35→
 36→      // Initialize UCI protocol
 37→      this.process.stdin.write('uci\n');
 38→      this.process.stdin.write('isready\n');
 39→
 40→      // Timeout after 5 seconds
 41→      setTimeout(() => {
 42→        if (!this.ready) {
 43→          this.process.stdout.removeListener('data', onData);
 44→          reject(new Error('Stockfish initialization timed out'));
 45→        }
 46→      }, 5000);
 47→    });
 48→  }
 49→
 50→  async getBestMove(fen, skillLevel = 10) {
 51→    if (!this.ready || !this.process) {
 52→      throw new Error('Stockfish not initialized');
 53→    }
 54→
 55→    return new Promise((resolve, reject) => {
 56→      // Set skill level
 57→      this.process.stdin.write(`setoption name Skill Level value ${Math.max(0, Math.min(20, skillLevel))}\n`);
 58→
 59→      let buffer = '';
 60→      const onData = (data) => {
 61→        buffer += data.toString();
 62→
 63→        if (buffer.includes('bestmove')) {
 64→          this.process.stdout.removeListener('data', onData);
 65→
 66→          const match = buffer.match(/bestmove ([a-h][1-8])([a-h][1-8])([qrbn])?/);
 67→          if (match) {
 68→            resolve({
 69→              from: match[1],
 70→              to: match[2],
 71→              promotion: match[3] || null
 72→            });
 73→          } else {
 74→            // bestmove (none) or parse failure
 75→            resolve(null);
 76→          }
 77→        }
 78→      };
 79→
 80→      this.process.stdout.on('data', onData);
 81→
 82→      // Send position and think
 83→      this.process.stdin.write('ucinewgame\n');
 84→      this.process.stdin.write(`position fen ${fen}\n`);
 85→      this.process.stdin.write('go movetime 1000\n');
 86→
 87→      // Timeout after 10 seconds
 88→      setTimeout(() => {
 89→        this.process.stdout.removeListener('data', onData);
 90→        reject(new Error('Stockfish move timed out'));
 91→      }, 10000);
 92→    });
 93→  }
 94→
 95→  terminate() {
 96→    if (this.process) {
 97→      this.process.stdin.write('quit\n');
 98→      this.process.kill();
 99→      this.process = null;
100→      this.ready = false;
101→    }
102→  }
103→}
104→
105→// Try to create a Stockfish player, return null if binary not available
106→async function createStockfishPlayer() {
107→  const player = new StockfishPlayer();
108→  try {
109→    await player.init();
110→    console.log('Stockfish engine initialized successfully');
111→    return player;
112→  } catch (err) {
113→    console.warn('Stockfish not available:', err.message);
114→    console.warn('Agent vs Engine mode will be disabled');
115→    return null;
116→  }
117→}
118→
119→module.exports = { StockfishPlayer, createStockfishPlayer };
