  1→// Chess Engine using Stockfish.js
  2→import { PIECE_TYPES, isWhitePiece } from './constants';
  3→import { indexToRowCol, rowColToIndex } from './moveValidation';
  4→
  5→class ChessEngine {
  6→  constructor() {
  7→    this.engine = null;
  8→    this.isReady = false;
  9→    this.skillLevel = 10; // 0-20, where 20 is strongest
 10→  }
 11→
 12→  async init() {
 13→    return new Promise((resolve) => {
 14→      // Check WebAssembly support
 15→      const wasmSupported = typeof WebAssembly === 'object' &&
 16→        WebAssembly.validate(Uint8Array.of(0x0, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00));
 17→
