 52→
 53→    // Piece placement
 54→    for (let row = 0; row < 8; row++) {
 55→      let emptyCount = 0;
 56→      for (let col = 0; col < 8; col++) {
 57→        const piece = board[row * 8 + col];
 58→        if (piece === 0) {
 59→          emptyCount++;
 60→        } else {
 61→          if (emptyCount > 0) {
 62→            fen += emptyCount;
 63→            emptyCount = 0;
 64→          }
 65→          const pieceType = Math.abs(piece);
 66→          const isWhite = isWhitePiece(piece);
 67→
 68→          let pieceChar = '';
 69→          switch (pieceType) {
 70→            case PIECE_TYPES.KING: pieceChar = 'k'; break;
 71→            case PIECE_TYPES.QUEEN: pieceChar = 'q'; break;
 72→            case PIECE_TYPES.ROOK: pieceChar = 'r'; break;
 73→            case PIECE_TYPES.BISHOP: pieceChar = 'b'; break;
 74→            case PIECE_TYPES.KNIGHT: pieceChar = 'n'; break;
 75→            case PIECE_TYPES.PAWN: pieceChar = 'p'; break;
 76→          }
