const { spawn } = require('child_process');

class StockfishPlayer {
  constructor() {
    this.process = null;
    this.ready = false;
  }

  async init() {
    return new Promise((resolve, reject) => {
      try {
        this.process = spawn('stockfish');
      } catch (err) {
        reject(new Error('Stockfish binary not found'));
        return;
      }

      this.process.on('error', (err) => {
        console.error('Stockfish process error:', err.message);
        this.ready = false;
        reject(err);
      });

      let initBuffer = '';
      const onData = (data) => {
        initBuffer += data.toString();
        if (initBuffer.includes('readyok')) {
          this.process.stdout.removeListener('data', onData);
          this.ready = true;
          resolve();
        }
      };

      this.process.stdout.on('data', onData);

      // Initialize UCI protocol
      this.process.stdin.write('uci\n');
      this.process.stdin.write('isready\n');

      // Timeout after 5 seconds
      setTimeout(() => {
        if (!this.ready) {
          this.process.stdout.removeListener('data', onData);
          reject(new Error('Stockfish initialization timed out'));
        }
      }, 5000);
    });
  }

  async getBestMove(fen, skillLevel = 10) {
    if (!this.ready || !this.process) {
      throw new Error('Stockfish not initialized');
    }

    return new Promise((resolve, reject) => {
      // Set skill level
      this.process.stdin.write(`setoption name Skill Level value ${Math.max(0, Math.min(20, skillLevel))}\n`);

      let buffer = '';
      const onData = (data) => {
        buffer += data.toString();

        if (buffer.includes('bestmove')) {
          this.process.stdout.removeListener('data', onData);

          const match = buffer.match(/bestmove ([a-h][1-8])([a-h][1-8])([qrbn])?/);
          if (match) {
            resolve({
              from: match[1],
              to: match[2],
              promotion: match[3] || null
            });
          } else {
            // bestmove (none) or parse failure
            resolve(null);
          }
        }
      };

      this.process.stdout.on('data', onData);

      // Send position and think
      this.process.stdin.write('ucinewgame\n');
      this.process.stdin.write(`position fen ${fen}\n`);
      this.process.stdin.write('go movetime 1000\n');

      // Timeout after 10 seconds
      setTimeout(() => {
        this.process.stdout.removeListener('data', onData);
        reject(new Error('Stockfish move timed out'));
      }, 10000);
    });
  }

  terminate() {
    if (this.process) {
      this.process.stdin.write('quit\n');
      this.process.kill();
      this.process = null;
      this.ready = false;
    }
  }
}

// Try to create a Stockfish player, return null if binary not available
async function createStockfishPlayer() {
  const player = new StockfishPlayer();
  try {
    await player.init();
    console.log('Stockfish engine initialized successfully');
    return player;
  } catch (err) {
    console.warn('Stockfish not available:', err.message);
    console.warn('Agent vs Engine mode will be disabled');
    return null;
  }
}

module.exports = { StockfishPlayer, createStockfishPlayer };

